/* Split one NAME,TYPE,VALUE record in place; returns 0 for malformed lines. */
static int split_record(char *line, char **name, char **value) {
    char *first = strchr(line, ',');
    if (!first) {
        return 0;
    }
    *first = 0;
    char *second = strchr(first + 1, ',');
    if (!second) {
        return 0;
    }
    *second = 0;
    *name = line;
    *value = second + 1;
    return 1;
}

static int semantist_run_input(char *data) {
    semantist_state_reset();
    uint8_t result[251];
    memset(result, 0, sizeof(result));
    uint8_t semantist_param_STR[251];
    memset(semantist_param_STR, 0, sizeof(semantist_param_STR));
    uint8_t semantist_param_SRC[81];
    memset(semantist_param_SRC, 0, sizeof(semantist_param_SRC));
    uint8_t semantist_param_REP[81];
    memset(semantist_param_REP, 0, sizeof(semantist_param_REP));
    char *save = NULL;
    for (char *line = strtok_r(data, "\n", &save); line; line = strtok_r(NULL, "\n", &save)) {
        char *name = NULL;
        char *value = NULL;
        if (!split_record(line, &name, &value)) {
            continue;
        }
        if (strcmp(name, "STR") == 0) {
            fill_string_value(semantist_param_STR, 251, value);
        }
        if (strcmp(name, "SRC") == 0) {
            fill_string_value(semantist_param_SRC, 81, value);
        }
        if (strcmp(name, "REP") == 0) {
            fill_string_value(semantist_param_REP, 81, value);
        }
    }
    __semantist_semantic_cycle(0);
    SEMANTIST_TIMING_BEGIN();
    REPLACE_CHARS(result, semantist_param_STR, semantist_param_SRC, semantist_param_REP);
    SEMANTIST_TIMING_END(semantist_timing_call_ns);
    escape_bytes(&result, sizeof(result));
    semantist_trace_bytes(&result, sizeof(result));
    semantist_trace_bytes(&semantist_param_STR, sizeof(semantist_param_STR));
    semantist_trace_bytes(&semantist_param_SRC, sizeof(semantist_param_SRC));
    semantist_trace_bytes(&semantist_param_REP, sizeof(semantist_param_REP));
    semantist_trace_mark('|');

    semantist_trace_end();
    return 0;
}

